var version := int(raw.get("version", 1))
if version == 1:
	# Version 1 stored decibels (0 is full volume) and called the locale "language"; it kept no record.
	data.volume = clampf(db_to_linear(float(raw.get("volume_db", 0.0))), 0.0, 1.0)
	data.locale = str(raw.get("language", "en"))
	return data

func test_a_version_1_file_keeps_its_volume_and_language():
	_write_raw('{"volume_db": -6.0, "language": "de"}')
	var data := SettingsStore.new(PATH).read()
	assert_almost_eq(float(data.volume), db_to_linear(-6.0), 0.001)
	assert_eq(data.locale, "de")
	assert_eq(data.version, SettingsStore.VERSION)

